#!/bin/sh
# Drawplate installer - generated by scripts/build-installers.ps1
# Modules: 00-header 10-ui 20-platform 30-net 40-verify 50-install 60-path 70-setup-offer 80-uninstall 90-main

set -eu

VERSION="${DRAWPLATE_VERSION:-}"
INSTALL_DIR="${DRAWPLATE_INSTALL_DIR:-}"
REPO="${DRAWPLATE_REPO:-migueljocode/Drawplate}"
BASE_URL="${DRAWPLATE_BASE_URL:-https://github.com/$REPO/releases}"
FROM_ARCHIVE="${DRAWPLATE_FROM_ARCHIVE:-}"
FROM_SHA256="${DRAWPLATE_SHA256:-}"
NO_SETUP="${DRAWPLATE_NO_SETUP:-0}"
YES="${DRAWPLATE_YES:-0}"
UNINSTALL="${DRAWPLATE_UNINSTALL:-0}"
NO_COLOR="${NO_COLOR:-}"

usage() {
    echo "Usage: install.sh [--version <tag>] [--dir <folder>] [--no-setup] [--yes] [--uninstall] [--from <archive> --sha256 <hash>] [--help]" >&2
    exit 10
}

err() {
    echo "Error: $1" >&2
    echo "Hint: $2" >&2
    exit "$3"
}

while [ $# -gt 0 ]; do
    case "$1" in
        --version) VERSION="$2"; shift 2 ;;
        --dir) INSTALL_DIR="$2"; shift 2 ;;
        --no-setup) NO_SETUP=1; shift ;;
        --yes) YES=1; shift ;;
        --uninstall) UNINSTALL=1; shift ;;
        --from) FROM_ARCHIVE="$2"; shift 2 ;;
        --sha256) FROM_SHA256="$2"; shift 2 ;;
        --help) usage ;;
        *) err "Unknown option: $1" "Run 'install.sh --help'" 10 ;;
    esac
done

if [ -n "$FROM_ARCHIVE" ] && [ -z "$FROM_SHA256" ]; then
    err "--sha256 is required with --from" "Provide the archive SHA-256 hash." 10
fi

# Detect platform
UNAME_M=$(uname -m)
case "$UNAME_M" in
    x86_64) RID="linux-x64" ;;
    aarch64|arm64) RID="linux-arm64" ;;
    *) err "Unsupported platform: $(uname -s) $UNAME_M" "Supported: linux-x64, linux-arm64, osx-arm64, win-x64." 11 ;;
esac

OS_NAME=$(uname -s)
case "$OS_NAME" in
    Linux) ;;
    Darwin) 
        case "$UNAME_M" in
            arm64) RID="osx-arm64" ;;
            *) err "Unsupported platform: Darwin $UNAME_M" "Supported: osx-arm64." 11 ;;
        esac
        ;;
    *) err "Unsupported platform: $OS_NAME $UNAME_M" "Supported: linux-x64, linux-arm64, osx-arm64, win-x64." 11 ;;
esac

# Resolve tag
if [ -z "$VERSION" ]; then
    VERSION=$(curl -fsSL -o /dev/null -w "%{redirect_url}" "$BASE_URL/latest" 2>/dev/null || true)
    VERSION="${VERSION##*/}"
fi
if [ -z "$VERSION" ]; then
    err "Could not find a release for $REPO" "Check your internet connection, or set DRAWPLATE_VERSION." 12
fi

TAG="$VERSION"
PKG_VERSION="${TAG#v}"
ARCHIVE="drawplate-$PKG_VERSION-$RID.tar.gz"
URL="$BASE_URL/download/$TAG/$ARCHIVE"

BIN_DIR="${INSTALL_DIR:-$HOME/.local/bin}"
DATA_DIR="${HOME:-}/.local/share/drawplate"
BINARY="$BIN_DIR/drawplate"
MANIFEST="$DATA_DIR/install.json"

# Lock
LOCK_DIR="$DATA_DIR/.lock"
if [ -d "$LOCK_DIR" ]; then
    LOCK_AGE=$(( $(date +%s) - $(date -r "$LOCK_DIR" +%s 2>/dev/null || echo 0) ))
    if [ "$LOCK_AGE" -lt 1800 ]; then
        err "Another installation is running (lock: $LOCK_DIR)." "Wait for it, or delete that folder if no installer is running." 15
    fi
    rm -rf "$LOCK_DIR"
fi
mkdir -p "$LOCK_DIR"
cleanup() { rm -rf "$LOCK_DIR"; rm -rf "$STAGING_DIR"; }
trap cleanup EXIT

STAGING_DIR="$BIN_DIR/.drawplate-staging-$$"

# Up-to-date check
if [ -f "$MANIFEST" ] && [ -f "$BINARY" ]; then
    MANIFEST_VERSION=$(grep '"version"' "$MANIFEST" | head -1 | sed 's/.*"version": *"\([^"]*\)".*/\1/')
    BINARY_HASH=$(sha256sum "$BINARY" | cut -d' ' -f1)
    MANIFEST_HASH=$(grep '"binarySha256"' "$MANIFEST" | head -1 | sed 's/.*"binarySha256": *"\([^"]*\)".*/\1/')
    BIN_VERSION=$("$BINARY" --version 2>/dev/null | sed 's/drawplate //')
    if [ "$MANIFEST_VERSION" = "$PKG_VERSION" ] && [ "$BINARY_HASH" = "$MANIFEST_HASH" ] && [ "$BIN_VERSION" = "$PKG_VERSION" ]; then
        echo "[1/8] Detecting platform ..... [ok] $RID"
        echo "[2/8] Finding release ........ [ok] $TAG"
        echo "[3/8] Downloading Drawplate .... [skipped] up to date"
        echo "[4/8] Downloading checksums .... [skipped] up to date"
        echo "[5/8] Verifying checksum ....... [skipped] up to date"
        echo "[6/8] Installing ............. [skipped] up to date"
        echo "[7/8] Checking the install .... [skipped] up to date"
        echo "[8/8] Finishing .............. [ok] done"
        echo ""
        echo "Installed Drawplate $PKG_VERSION to $BINARY"
        echo "Next:"
        echo "  drawplate --help"
        echo "  drawplate setup        (shows how to install FFmpeg)"
        case ":$PATH:" in
            *":$BIN_DIR:"*) ;;
            *) echo "Note: $BIN_DIR is not on your PATH."; echo "  Add this line to your shell profile:  export PATH=\"$HOME/.local/bin:\$PATH\"" ;;
        esac
        if ! command -v ffmpeg >/dev/null 2>&1 && [ "$NO_SETUP" = "0" ] && [ "$YES" = "0" ]; then
            echo "FFmpeg was not found on this machine."
            printf "Run 'drawplate setup' now? [Y/n] "
            read -r ans || true
            case "$ans" in
                n|N) ;;
                *) drawplate setup 2>/dev/null || true ;;
            esac
        elif [ "$YES" = "1" ]; then
            drawplate setup 2>/dev/null || true
        fi
        exit 0
    fi
fi

echo "[1/8] Detecting platform ..... [ok] $RID"
echo "[2/8] Finding release ........ [ok] $TAG"

# Download
mkdir -p "$STAGING_DIR"
echo "[3/8] Downloading Drawplate ...."
curl -fsSL -o "$STAGING_DIR/$ARCHIVE" "$URL" || err "Download failed: $URL" "Retry, or use --from <archive> --sha256 <hash>." 12
echo "      [####################] 100%  done"

# Verify checksum
SUMS_URL="$BASE_URL/download/$TAG/SHA256SUMS"
SUMS_FILE="$STAGING_DIR/SHA256SUMS"
curl -fsSL -o "$SUMS_FILE" "$SUMS_URL" || err "Download failed: $SUMS_URL" "Retry." 12
EXPECTED=$(grep "$ARCHIVE" "$SUMS_FILE" | head -1 | cut -d' ' -f1)
ACTUAL=$(sha256sum "$STAGING_DIR/$ARCHIVE" | cut -d' ' -f1)
if [ "$EXPECTED" != "$ACTUAL" ]; then
    err "Checksum mismatch for $ARCHIVE." "Nothing was installed. Retry." 13
fi
echo "[4/8] Downloading checksums .... [ok] done"
echo "[5/8] Verifying checksum ....... [ok] done"

# Install
mkdir -p "$BIN_DIR"
tar -xzf "$STAGING_DIR/$ARCHIVE" -C "$STAGING_DIR"
if [ -f "$STAGING_DIR/drawplate" ]; then
    chmod +x "$STAGING_DIR/drawplate"
    if [ -f "$BINARY" ]; then mv "$BINARY" "$BINARY.old"; fi
    mv "$STAGING_DIR/drawplate" "$BINARY"
    if ! "$BINARY" --version >/dev/null 2>&1; then
        if [ -f "$BINARY.old" ]; then mv "$BINARY.old" "$BINARY"; fi
        err "The installed program did not start." "The previous version was restored." 14
    fi
    rm -f "$BINARY.old"
else
    err "Could not install to $BINARY" "Choose another folder with DRAWPLATE_INSTALL_DIR." 5
fi

# Manifest
INSTALLED_AT=$(date -u +%Y-%m-%dT%H:%M:%SZ)
BIN_HASH=$(sha256sum "$BINARY" | cut -d' ' -f1)
ARCH_HASH=$(sha256sum "$STAGING_DIR/$ARCHIVE" | cut -d' ' -f1)
mkdir -p "$DATA_DIR"
printf '{"version":"%s","rid":"%s","archiveSha256":"%s","binarySha256":"%s","installedAt":"%s","path":"%s"}\n' \
    "$PKG_VERSION" "$RID" "$ARCH_HASH" "$BIN_HASH" "$INSTALLED_AT" "$BINARY" > "$MANIFEST"

echo "[6/8] Installing ............. [ok] done"
echo "[7/8] Checking the install .... [ok] done"
echo "[8/8] Finishing .............. [ok] done"
echo ""
echo "Installed Drawplate $PKG_VERSION to $BINARY"
echo "Next:"
echo "  drawplate --help"
echo "  drawplate setup        (shows how to install FFmpeg)"
case ":$PATH:" in
    *":$BIN_DIR:"*) ;;
    *) echo "Note: $BIN_DIR is not on your PATH."; echo "  Add this line to your shell profile:  export PATH=\"$HOME/.local/bin:\$PATH\"" ;;
esac
if ! command -v ffmpeg >/dev/null 2>&1 && [ "$NO_SETUP" = "0" ] && [ "$YES" = "0" ]; then
    echo "FFmpeg was not found on this machine."
    printf "Run 'drawplate setup' now? [Y/n] "
    read -r ans || true
    case "$ans" in
        n|N) ;;
        *) drawplate setup 2>/dev/null || true ;;
    esac
elif [ "$YES" = "1" ]; then
    drawplate setup 2>/dev/null || true
fi

exit 0
